// W3-0 Prüfer: sichtbaren Text (nach Hydration) auf Muster durchsuchen
// Aufruf: node w30-text.mjs <basis> <regex> <pfad...>
import { chromium } from "playwright";
const [basis, muster, ...pfade] = process.argv.slice(2);
const re = new RegExp(muster, "g");
const b = await chromium.launch();
const p = await b.newPage();
for (const pfad of pfade) {
  try {
    let r = null;
    for (let v = 0; v < 12; v++) {
      try { r = await p.goto(basis + pfad, { waitUntil: "load", timeout: 180000 }); if (r && r.status() < 500) break; } catch (e) { if (v === 11) throw e; }
      await new Promise((ok) => setTimeout(ok, 20000));
    }
    await p.waitForTimeout(1200);
    const info = await p.evaluate(() => {
      const teile = { nav: document.querySelector("header")?.innerText || "", fuss: document.querySelector("footer")?.innerText || "", main: document.querySelector("main")?.innerText || document.body.innerText, title: document.title };
      const attr = [...document.querySelectorAll("[aria-label],[title],[placeholder],[alt]")].map((e) => [e.getAttribute("aria-label"), e.getAttribute("title"), e.getAttribute("placeholder"), e.getAttribute("alt")].filter(Boolean).join(" ")).join(" | ");
      teile.attr = attr;
      return teile;
    });
    const out = [];
    for (const [k, t] of Object.entries(info)) {
      const zeilen = t.split(/\n| \| /).filter((z) => { re.lastIndex = 0; return re.test(z); });
      if (zeilen.length) out.push(`  [${k}] ${zeilen.length}: ` + [...new Set(zeilen)].slice(0, 6).map((z) => z.trim().slice(0, 140)).join(" ¦ "));
    }
    console.log(`${pfad} ${r?.status()}${out.length ? "\n" + out.join("\n") : " sauber"}`);
  } catch (e) { console.log(pfad, "FEHLER", String(e).slice(0, 100)); }
}
await b.close();

