// QM Welle 3: Suchlauf nach "ß" auf allen /ch-Seiten (gerendertes HTML ohne JS-Payload)
// Aufruf: node ss-scan.mjs <basis> <pfad...>   (Pfade ohne /ch-Präfix)
const basis = process.argv[2];
const pfade = process.argv.slice(3);
let funde = 0;
for (const pfad of pfade) {
  const url = basis + "/ch" + (pfad === "/" ? "" : pfad);
  let html;
  try {
    const r = await fetch(url);
    if (r.status !== 200) { console.log(`${pfad} STATUS ${r.status}`); funde++; continue; }
    html = await r.text();
  } catch (e) { console.log(`${pfad} FEHLER ${String(e).slice(0, 80)}`); funde++; continue; }

  const treffer = [];
  // 1) JSON-LD
  for (const m of html.matchAll(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)) {
    const t = m[1];
    if (t.includes("ß")) {
      const stellen = [...t.matchAll(/.{0,40}ß.{0,40}/g)].map((x) => x[0].replace(/\s+/g, " "));
      treffer.push(`[json-ld] ${stellen.length}: ` + [...new Set(stellen)].slice(0, 5).join(" ¦ "));
    }
  }
  // 2) Meta/Title
  for (const m of html.matchAll(/<(title)[^>]*>([^<]*)<\/title>|<meta[^>]*(?:name|property)="(description|og:title|og:description|twitter:title|twitter:description)"[^>]*content="([^"]*)"/g)) {
    const inhalt = m[2] || m[4] || "";
    if (inhalt.includes("ß")) treffer.push(`[meta ${m[1] || m[3]}] ${inhalt.slice(0, 120)}`);
  }
  // 3) Sichtbarer Text + Attribute: Skripte/Styles entfernen, dann Attribute und Text prüfen
  let rest = html.replace(/<script[\s\S]*?<\/script>/g, "").replace(/<style[\s\S]*?<\/style>/g, "");
  for (const m of rest.matchAll(/(aria-label|title|placeholder|alt)="([^"]*ß[^"]*)"/g)) {
    treffer.push(`[attr ${m[1]}] ${m[2].slice(0, 100)}`);
  }
  const text = rest.replace(/<[^>]+>/g, "\n");
  const zeilen = [...new Set(text.split("\n").map((z) => z.trim()).filter((z) => z.includes("ß")))];
  if (zeilen.length) treffer.push(`[text] ${zeilen.length}: ` + zeilen.slice(0, 6).map((z) => z.slice(0, 120)).join(" ¦ "));

  if (treffer.length) { funde++; console.log(`${pfad}\n  ` + treffer.join("\n  ")); }
}
console.log(funde ? `\n${funde} Seiten mit Funden/Fehlern` : "alle Seiten sauber");

