// QM Welle 3: HTTP/SEO-Prüfung neuer Seiten in allen Länder- und Sprachfassungen
// Aufruf: node seo-check.mjs <basis> <seite...>  (Seitenpfad ohne Präfix, z. B. /rechner/flaechenpass)
const basis = process.argv[2];
const seiten = process.argv.slice(3);
const PRAEFIXE = ["", "/de", "/at", "/ch", "/en", "/en/de", "/en/at", "/en/ch"];
const LANG = { "": "de", "/de": "de-DE", "/at": "de-AT", "/ch": "de-CH", "/en": "en", "/en/de": "en", "/en/at": "en", "/en/ch": "en" };
let fehler = 0;

async function hole(url) {
  for (let v = 0; v < 20; v++) {
    try {
      const r = await fetch(url, { signal: AbortSignal.timeout(120000), redirect: "manual" });
      if (r.status >= 500) { await new Promise((ok) => setTimeout(ok, 15000)); continue; }
      return { status: r.status, html: r.status === 200 ? await r.text() : "" };
    } catch { await new Promise((ok) => setTimeout(ok, 15000)); }
  }
  return { status: 0, html: "" };
}

for (const seite of seiten) {
  for (const p of PRAEFIXE) {
    const pfad = p + seite;
    const { status, html } = await hole(basis + pfad);
    const probleme = [];
    if (status !== 200) probleme.push(`Status ${status}`);
    else {
      const lang = (html.match(/<html[^>]*\slang="([^"]*)"/) || [])[1] || "";
      if (lang !== LANG[p]) probleme.push(`lang="${lang}" statt "${LANG[p]}"`);
      const robots = (html.match(/<meta[^>]*name="robots"[^>]*content="([^"]*)"/) || [])[1] || "";
      if (!/noindex/.test(robots)) probleme.push(`robots="${robots}" ohne noindex`);
      const canon = (html.match(/<link[^>]*rel="canonical"[^>]*href="([^"]*)"/) || [])[1] || "";
      const hreflang = [...html.matchAll(/<link[^>]*rel="alternate"[^>]*hreflang="([^"]*)"/g)].map((m) => m[1]);
      if (probleme.length === 0 && (canon || hreflang.length)) probleme.push(`INFO canonical=${canon || "-"} hreflang=[${hreflang.join(",")}]`);
    }
    const echt = probleme.filter((x) => !x.startsWith("INFO"));
    if (echt.length) fehler++;
    if (probleme.length) console.log(`${pfad}: ${probleme.join(" | ")}`);
    await new Promise((ok) => setTimeout(ok, 200));
  }
}
console.log(fehler ? `\n${fehler} Fassungen mit Problemen` : "\nalle Fassungen: 200, lang korrekt, noindex gesetzt");

